using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using NUnit.Framework;
using Olca.Core.Domain;
using Olca.Core.Logic.Customization;
using Olca.Core.Logic.Dungeon;
using Olca.Core.Logic.Battle;
using Olca.Core.Logic.Integration;
using Olca.Tests.Mocks;
namespace Olca.Tests {
 public class CustomizationAbilityTests {
  CustomizationLoadoutSources Sources(){var catalog=new CustomizationCatalog("fixture-board",new PartsBoardDefinition(2,1,new[]{new Vector2Int(0,0),new Vector2Int(1,0)}),new[]{"a"},new Dictionary<string,PartShape>{{"dot",new PartShape(new[]{Vector2Int.Zero})}},null);return new CustomizationLoadoutSources(catalog,new CustomizationProgress{OwnedAccessoryIds=new[]{"a"},EquippedAccessoryIds=new[]{"a"},OwnedParts=new[]{new CustomizationItemCount{Id="dot",Count=2}},BoardId="fixture-board",UnlockedCells=new[]{new CustomizationCell{X=0,Y=0},new CustomizationCell{X=1,Y=0}},Placements=new[]{new SavedPartPlacement{InstanceId="p",PartId="dot",X=0,Y=0},new SavedPartPlacement{InstanceId="q",PartId="dot",X=1,Y=0}}});}
  ResolvedCustomizationAbilities Abilities(bool floating=true)=>new CustomizationAbilityCatalog("fixture-abilities-v1",new Dictionary<string,CustomizationAbilityValue>{{"a",new CustomizationAbilityValue(statuses:new TimedStatusResistances(poison:5),floating:floating)}},new Dictionary<string,CustomizationAbilityValue>{{"dot",new CustomizationAbilityValue(new ElementResistances(fire:-150,water:80),new TimedStatusResistances(poison:60,paralyze:20))}}).Resolve(Sources());
  PlayerCharacter Player(bool floating=true){var p=new PlayerCharacter(100,statusResistances:new TimedStatusResistances(poison:10));p.SetElementResistances(new ElementResistances(fire:100));p.SetDepartureAbilities(Abilities(floating));return p;}
  [Test] public void 全供給元と基礎値を合算後に一度だけ属性上下限を適用し状態耐性を合算する(){var p=Player();Assert.AreEqual(-100,p.Resistances.Fire);Assert.AreEqual(100,p.Resistances.Water);Assert.AreEqual(135,p.StatusResistances.Poison);Assert.AreEqual(40,p.StatusResistances.Paralyze);var battle=new BattleSystem(p,new List<Enemy>{new Enemy("e","テスト",1000,ElementType.None,new Vector2Int(4,0))},new Deck(new List<Card>()),customGaugeSpeed:0,randomProvider:new MockRandomProvider());p.ApplyConfusion(120);p.ApplyParalysis(120);battle.RunLogicalFrame(()=>{});Assert.AreEqual(120,p.ConfusionRemainingFrames);Assert.AreEqual(72,p.ParalysisRemainingFrames);}
  [Test] public void 解決結果と登録元は不変で同種個体を失わず未知対応を拒否する(){var abilities=Abilities();var dto=abilities.Capture();Assert.AreEqual(3,dto.Sources.Length);dto.Sources[0].Floating=false;dto.Sources[1].Fire=999;Assert.IsTrue(abilities.Floating);Assert.AreEqual(-150,abilities.Capture().Sources[1].Fire);var empty=new CustomizationAbilityCatalog("empty",null,null);Assert.Throws<ArgumentException>(()=>empty.Resolve(Sources()));}
  [TestCase(true)][TestCase(false)] public void 勝利後は一時フロートだけを解除し常時能力と耐性を次戦へ保持する(bool permanent){var p=Player(permanent);p.TerrainState.IsFloating=true;var enemy=new Enemy("e","テスト",100,ElementType.None,new Vector2Int(4,0));var battle=new BattleSystem(p,new List<Enemy>{enemy},new Deck(new List<Card>()),randomProvider:new MockRandomProvider());battle.RunLogicalFrame(()=>enemy.TakeDamage(99999,ElementType.None));Assert.IsFalse(p.TerrainState.IsTemporarilyFloating);Assert.AreEqual(permanent,p.TerrainState.IsFloating);Assert.AreEqual(135,p.StatusResistances.Poison);Assert.AreEqual(-100,p.Resistances.Fire);}
  [Test] public void 常時フロートは一時分解除や否定で失われず基礎なしの敵側は従来どおり解除する(){var p=Player();p.TerrainState.IsFloating=false;p.TerrainState.Clear();Assert.IsTrue(p.TerrainState.IsFloating);var enemyState=new BattleTerrainState();enemyState.IsFloating=true;enemyState.Clear();Assert.IsFalse(enemyState.IsFloating);}
  [Test] public void 変身中の属性耐性置換は確定仕様どおりで解除後に装備耐性へ戻る(){var p=Player();p.BeginTransformationDefense(new ElementResistances(fire:20),ElementType.Water);Assert.AreEqual(20,p.ActiveResistances.Fire);Assert.AreEqual(135,p.ActiveStatusResistances.Poison);p.EndTransformationDefense();Assert.AreEqual(-100,p.ActiveResistances.Fire);}
  [TestCase(true)][TestCase(false)] public void 戦闘破棄でも一時フロートは消え常時分だけ残る(bool permanent){var p=Player(permanent);p.TerrainState.IsFloating=true;var b=new BattleSystem(p,new List<Enemy>{new Enemy("e","テスト",100,ElementType.None,new Vector2Int(4,0))},new Deck(new List<Card>()),randomProvider:new MockRandomProvider());typeof(BattleSystem).GetMethod("AbandonForCheckpoint",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(b,null);Assert.IsFalse(p.TerrainState.IsTemporarilyFloating);Assert.AreEqual(permanent,p.TerrainState.IsFloating);Assert.AreEqual(135,p.StatusResistances.Poison);}
  string directory;
  DungeonBattleManager Create(out DungeonCheckpointSession session,out CheckpointDefinitions definitions,PlayerCharacter supplied=null){directory=Path.Combine(Path.GetTempPath(),"olca-abilities-"+Guid.NewGuid().ToString("N"));var map=DungeonConfig.CreateTestDungeon(20,30,3);var deck=new Deck(new List<Card>{CardRewardSystem.CreateFallbackCard("sword",CardRarity.Normal)});var initial=DungeonCheckpointSession.CreateDefault(map,deck);definitions=initial.Definitions;session=new DungeonCheckpointSession(definitions,new Olca.Unity.FileCheckpointStore(definitions,directory));return new DungeonBattleManager(map,supplied??Player(),deck,new MockRandomProvider(),new MockLogger(),checkpoints:session);}
  [TearDown] public void Cleanup(){if(directory!=null&&Directory.Exists(directory))Directory.Delete(directory,true);}
  [Test] public void 通常出撃捕捉とファイル再読込で能力を復元し現在定義に依存せず二重適用しない(){var game=Create(out var session,out var definitions);var store=new Olca.Unity.FileCheckpointStore(definitions,directory);var before=File.ReadAllBytes(store.ActivePath);var snapshot=store.Read();Assert.IsNotNull(snapshot,store.ReadError);Assert.AreEqual(100,snapshot.Player.FireResistance);Assert.AreEqual(10,snapshot.Player.PoisonResistance);Assert.AreEqual(3,snapshot.Player.CustomizationAbilities.Sources.Length);for(int i=0;i<3;i++){Assert.IsTrue(CheckpointCodec.TryRestore(snapshot,definitions,out var restored,out var error),error);Assert.AreEqual(-100,restored.Player.Resistances.Fire);Assert.AreEqual(135,restored.Player.StatusResistances.Poison);Assert.IsTrue(restored.Player.TerrainState.IsFloating);snapshot=PortableCheckpointJson.Decode(PortableCheckpointJson.Encode(snapshot));}CollectionAssert.AreEqual(before,File.ReadAllBytes(store.ActivePath));Assert.Throws<InvalidOperationException>(()=>game.Dungeon.Player.SetDepartureAbilities(Abilities()));}
  [TestCase(250,-50)][TestCase(400,100)][TestCase(-400,-100)] public void 基礎耐性も合算前の原値を保存し負補正で上限から戻る場合に復帰結果が変わらない(int baseline,int expected){var p=Player();p.SetElementResistances(new ElementResistances(fire:baseline));Create(out var session,out var definitions,p);Assert.AreEqual(expected,p.Resistances.Fire);var dto=session.Store.Read();Assert.AreEqual(baseline,dto.Player.RawBaseFireResistance);Assert.IsTrue(CheckpointCodec.TryRestore(dto,definitions,out var restored,out var error),error);Assert.AreEqual(expected,restored.Player.Resistances.Fire);}
  [Test] public void 基礎状態耐性も保存し戦闘限定補正やフロートの未保存許可には拡大しない(){var game=Create(out var session,out _);var method=typeof(DungeonCheckpointSession).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Instance);var before=PortableCheckpointJson.Encode(session.Store.Read());var p=game.Dungeon.Player;p.SetBattleStatusResistances(new TimedStatusResistances(poison:1));Assert.Throws<TargetInvocationException>(()=>method.Invoke(session,new object[]{game.Dungeon,CheckpointBoundary.RewardCompleted,null}));p.SetBattleStatusResistances(TimedStatusResistances.Neutral);p.TerrainState.IsFloating=true;Assert.Throws<TargetInvocationException>(()=>method.Invoke(session,new object[]{game.Dungeon,CheckpointBoundary.RewardCompleted,null}));p.TerrainState.Clear();Assert.IsNotNull(method.Invoke(session,new object[]{game.Dungeon,CheckpointBoundary.RewardCompleted,null}));CollectionAssert.AreEqual(before,PortableCheckpointJson.Encode(session.Store.Read()));}
  [TestCase("version")][TestCase("status")][TestCase("duplicate")][TestCase("kind")][TestCase("identity")][TestCase("raw")][TestCase("header")][TestCase("missing")]
  public void 壊れた能力保存は原本を変更せず復帰拒否する(string errorCase){Create(out var session,out var definitions);var store=new Olca.Unity.FileCheckpointStore(definitions,directory);var before=File.ReadAllBytes(store.ActivePath);var bad=session.Store.Read();if(errorCase=="version")bad.Player.CustomizationAbilities.Version=2;if(errorCase=="status")bad.Player.PoisonResistance=-1;if(errorCase=="duplicate")bad.Player.CustomizationAbilities.Sources[1]=bad.Player.CustomizationAbilities.Sources[0].Copy();if(errorCase=="kind")bad.Player.CustomizationAbilities.Sources[0].Kind="unknown";if(errorCase=="identity")bad.Player.CustomizationAbilities.Sources[0].ItemId="other";if(errorCase=="raw")bad.Player.RawBaseFireResistance=null;if(errorCase=="header")bad.Player.FireResistance=0;if(errorCase=="missing")bad.Player.CustomizationAbilities.Sources=null;Assert.IsFalse(CheckpointCodec.TryRestore(bad,definitions,out _,out _));CollectionAssert.AreEqual(before,File.ReadAllBytes(store.ActivePath));}
  [Test] public void 旧保存の能力欠損と状態耐性欠損は中立として読込だけで書き換えない(){Create(out var session,out var definitions);var old=session.Store.Read();old.Player.CustomizationAbilities=null;old.Player.RawBaseFireResistance=old.Player.RawBaseWaterResistance=old.Player.RawBaseWindResistance=old.Player.RawBaseEarthResistance=null;old.Player.PoisonResistance=0;var raw=System.Text.Encoding.UTF8.GetString(PortableCheckpointJson.Serialize(old));foreach(string name in new[]{"RawBaseFireResistance","RawBaseWaterResistance","RawBaseWindResistance","RawBaseEarthResistance","CustomizationAbilities","PoisonResistance","ParalyzeResistance","ConfusionResistance","BlindResistance"})raw=System.Text.RegularExpressions.Regex.Replace(raw,"\""+name+"\":(?:null|0),","");var decoded=PortableCheckpointJson.Deserialize<CheckpointDto>(System.Text.Encoding.UTF8.GetBytes(raw));Assert.IsTrue(CheckpointCodec.TryRestore(decoded,definitions,out var restored,out var error),error);Assert.IsNull(restored.Player.DepartureAbilities);Assert.IsTrue(restored.Player.StatusResistances.IsNeutral);Assert.IsFalse(restored.Player.TerrainState.IsFloating);}
  [Test] public void 不変装備補正の再読取は新しい基礎値へ合算し公開コピーの変更で変わらない(){var abilities=Abilities();Assert.AreEqual(-50,abilities.CombineElements(new ElementResistances(fire:250)).Fire);Assert.AreEqual(100,abilities.CombineElements(new ElementResistances(fire:400)).Fire);var copy=abilities.Capture();foreach(var source in copy.Sources){source.Fire=999;source.Poison=0;source.Floating=false;}Assert.AreEqual(-100,abilities.CombineElements(ElementResistances.Neutral).Fire);Assert.AreEqual(125,abilities.CombineStatuses(TimedStatusResistances.Neutral).Poison);Assert.AreEqual(135,abilities.CombineStatuses(new TimedStatusResistances(poison:10)).Poison);Assert.IsTrue(abilities.Floating);Assert.AreEqual(-300,abilities.Capture().Sources.Sum(v=>v.Fire));}
  [Test] public void 出撃構築後は未設定だった装備能力と成長も後付けできない(){var p=new PlayerCharacter(100);Create(out _,out _,p);Assert.Throws<InvalidOperationException>(()=>p.SetDepartureAbilities(Abilities()));Assert.Throws<InvalidOperationException>(()=>p.SetAttackGrowth(new AttackMilestoneGrowth(1,100,0)));Assert.Throws<InvalidOperationException>(()=>p.SetDepartureStyle(DepartureStyleDefinition.Basic));}
  [Test] public void 合算のnull入力は既存の引数エラー契約を維持する(){var abilities=Abilities();Assert.AreEqual("values",Assert.Throws<ArgumentException>(()=>abilities.CombineElements(null)).ParamName);Assert.AreEqual("values",Assert.Throws<ArgumentNullException>(()=>abilities.CombineStatuses(null)).ParamName);Assert.Throws<ArgumentNullException>(()=>ElementResistances.Combine((ElementResistances[])null));Assert.Throws<ArgumentNullException>(()=>TimedStatusResistances.Combine((TimedStatusResistances[])null));}
 }
}
